using System.Collections.Generic;
using Astrea;
using UnityEngine;

namespace LittleLeo;

public class VFXHandler : ReferenceSingleton<VFXHandler>
{
	[Header("Save System")]
	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private bool VFXDisabled;

	private List<VFXHolder> VFXHolders = new List<VFXHolder>();

	public void SetVFXDisabled(bool value)
	{
		VFXDisabled = value;
	}

	public bool IsVFXEnabled()
	{
		return !VFXDisabled;
	}

	public List<VFXHolder> GetVFXHolders()
	{
		return VFXHolders;
	}

	public void AddToVFXHolders(VFXHolder VFXHolder)
	{
		VFXHolders.Add(VFXHolder);
	}

	protected void Start()
	{
		if (saveSystem.HasDisableVFXSettingSaveKey())
		{
			SetVFXDisabled(saveSystem.LoadDisableVFXSetting());
		}
	}

	public VFXHolder GetVFXInstanceFromVFXHoldersAndRemoveItFromList(GameObject VFXOwner, Effect effectVFX)
	{
		VFXHolder vFXHolder = null;
		for (int i = 0; i < VFXHolders.Count; i++)
		{
			VFXHolder vFXHolder2 = VFXHolders[i];
			if (vFXHolder2.VFXOwner == VFXOwner && vFXHolder2.effectVFX == effectVFX)
			{
				vFXHolder = vFXHolder2;
				break;
			}
		}
		if (vFXHolder != null)
		{
			VFXHolders.Remove(vFXHolder);
		}
		return vFXHolder;
	}

	public VFXHolder GetVFXInstanceFromVFXHolders(GameObject VFXOwner, Effect effectVFX)
	{
		VFXHolder result = null;
		for (int i = 0; i < VFXHolders.Count; i++)
		{
			VFXHolder vFXHolder = VFXHolders[i];
			if (vFXHolder.VFXOwner == VFXOwner && vFXHolder.effectVFX == effectVFX)
			{
				result = vFXHolder;
				break;
			}
		}
		return result;
	}

	public GameObject GetVFX(GameObject vfxPrefab, float storeDelay = 0f)
	{
		GameObject gameObject = null;
		gameObject = GetVFXFromPool(vfxPrefab.name, storeDelay);
		if (gameObject == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
			gameObject = GetVFXFromPool(vfxPrefab.name, storeDelay);
		}
		return gameObject;
	}

	public GameObject GetVFX(GameObject vfxPrefab, Vector3 position, Transform parent, float storeDelay = 0f)
	{
		GameObject gameObject = null;
		gameObject = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
		if (gameObject == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
			gameObject = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
		}
		gameObject.transform.SetParent(parent);
		return gameObject;
	}

	public GameObject GetVFX(GameObject vfxPrefab, Vector3 position, float storeDelay = 0f)
	{
		GameObject gameObject = null;
		gameObject = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
		if (gameObject == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
			gameObject = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
		}
		return gameObject;
	}

	public void SpawnVFX(GameObject vfxPrefab, Vector3 position, float storeDelay = 0f)
	{
		if (!VFXDisabled && GetVFXFromPool(vfxPrefab.name, position, storeDelay) == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
			GetVFXFromPool(vfxPrefab.name, position, storeDelay);
		}
	}

	public void SpawnVFX(GameObject vfxPrefab, float storeDelay = 0f)
	{
		if (!VFXDisabled && GetVFXFromPool(vfxPrefab.name, storeDelay) == null)
		{
			ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
			GetVFXFromPool(vfxPrefab.name, storeDelay);
		}
	}

	public void SpawnVFX(GameObject vfxPrefab, Vector3 position, Transform parent, float storeDelay = 0f)
	{
		if (!VFXDisabled)
		{
			GameObject vFXFromPool = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
			if (vFXFromPool == null)
			{
				ReferenceSingleton<PoolHandler>.Instance.AddPool(vfxPrefab);
				vFXFromPool = GetVFXFromPool(vfxPrefab.name, position, storeDelay);
			}
			vFXFromPool.transform.SetParent(parent);
		}
	}

	private GameObject GetVFXFromPool(string vfxPrefabName, float storeDelay = 0f)
	{
		if (storeDelay > 0f)
		{
			return ReferenceSingleton<PoolHandler>.Instance.GetObject(vfxPrefabName, storeDelay);
		}
		return ReferenceSingleton<PoolHandler>.Instance.GetObject(vfxPrefabName);
	}

	private GameObject GetVFXFromPool(string vfxPrefabName, Vector3 position, float storeDelay = 0f)
	{
		if (storeDelay > 0f)
		{
			return ReferenceSingleton<PoolHandler>.Instance.GetObject(vfxPrefabName, position, storeDelay);
		}
		return ReferenceSingleton<PoolHandler>.Instance.GetObject(vfxPrefabName, position);
	}

	public void OnDisableVFXToggle(bool value)
	{
		SetVFXDisabled(value);
	}

	public void StoreAllVFX()
	{
		for (int i = 0; i < VFXHolders.Count; i++)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(VFXHolders[i].VFXInstance);
		}
		VFXHolders.Clear();
	}
}
